98    const starting = new Map<cordis.Fiber, resourcesModule.PluginStatus>();
99
100    function recordPluginFailure(row: resourcesModule.PluginStatus, error: unknown): void {
101      //G 启动真的失败才记为失败，错误原文给标准错误排查。
102      const text = textModule.getErrorMessage(error);
103      console.error(`插件 ${row.name} 没挂上：${text}`);
104      row.state = 'failed';
105      row.error = text;
106      if (/Cannot find module/iu.test(text)) {
107        //G health 和教程只给出找不到入口的原因，不带模块系统的绝对路径。
108        row.error = '找不到这个插件（自带名单里没有，也没有对应的入口文件）';
109      }
110    }
111
112    //M 以真实 fiber 为键。等依赖或超时后继续启动的插件都能更新自己的那一行。
113    app.on('internal/status', (fiber) => {
114      const row = starting.get(fiber);
115      if (row === undefined) return;
116
117      if (fiber.state === cordis.FiberState.ACTIVE) {
118        starting.delete(fiber);
119        row.state = 'ok';
120        row.error = '';
121        return;
122      }
123      if (fiber.state !== cordis.FiberState.FAILED) return;
124
125      //M 缺依赖时首轮等待可能早已返回，由状态事件取出随后启动失败的原因。
126      void fiber.await().catch((error: unknown) => {
127        if (!starting.delete(fiber)) return;
128
129        recordPluginFailure(row, error);
130      });
131    }, { prepend: true });
132
```

### 解释
- L84：拿到配置里的 plugins 和单插件等待上限。
- L88–L91：试运行（基地换版前先试跑）只留 http，够做健康检查，不开渠道。
- L94：守卫：试运行却没配 http → 抛错。

